public class Main { public static void main(String[] args) {var s=new java.util.Scanner(System.in); int[][] a={{-3,0,3},{2,-1,0},{1,3,-2}};if(s.hasNextInt())for(int r=0;r<3;r++)for(int c=0;c<3;c++)a[r][c]=s.nextInt();for(int pass=0;pass<2;pass++)for(int r=0;r<2-pass;r++)if(java.util.Arrays.stream(a[r]).sum()>java.util.Arrays.stream(a[r+1]).sum()){int[] row=a[r];a[r]=a[r+1];a[r+1]=row;}for(int[] row:a){for(int v:row)System.out.printf(java.util.Locale.ROOT,"%.12e ",(double)v);System.out.println();}} }
